-- GoWithDME: DAFTAR KONSER PER KOTA (v3) - tanpa duplikat, lengkap dengan harga, poster, dan link tiket.
-- Jalankan di Supabase > SQL Editor > New query > tempel seluruh isi file ini > Run.
-- Prasyarat: schema.sql, schema_tahap2.sql, schema_admin.sql, schema_kota.sql, schema_komunitas.sql sudah pernah dijalankan.
-- AMAN DIJALANKAN BERULANG KALI: tidak membuat baris ganda.
-- Data per 16 Nov 2026. Sumber: infokonser.id, jadwal.events, tiket.com / situs resmi (lihat ticket_url). Cek ulang harga di penjual tiket sebelum tayang.
-- Poster = URL gambar dari halaman event sumber. Poster milik penyelenggara: minta izin atau ganti lewat admin.

-- ===== 1. Kota baru (kolom di js/regions.js juga sudah ditambah) =====
insert into cities(province_id,name,slug)
select p.id,v.n,v.s from (values
  ('DI Yogyakarta','Sleman','sleman'),
  ('DI Yogyakarta','Bantul','bantul'),
  ('Jawa Timur','Lamongan','lamongan')
) as v(prov,n,s) join provinces p on p.name=v.prov
on conflict (slug) do nothing;

-- ===== 2. Kunci anti-duplikat =====
-- Kunci = kota + tanggal mulai + 10 huruf/angka pertama judul (huruf kecil, tanpa spasi/tanda baca).
create or replace function gwm_norm(t text) returns text language sql immutable as
$$ select regexp_replace(lower(coalesce(t,'')),'[^a-z0-9]','','g') $$;

-- ===== 3. Bersihkan duplikat yang SUDAH ada =====
-- Yang dipertahankan: yang terbit > punya poster > punya link tiket > paling lama.
-- Baris duplikat yang sudah dipakai fitur "ajakan barengan" TIDAK dihapus (aman).
with ranked as (
  select id, row_number() over (
    partition by city_id, event_date, left(gwm_norm(title),10)
    order by (status='published') desc, (poster_url is not null) desc, (ticket_url is not null) desc, created_at asc, id
  ) rn
  from events
)
delete from events e using ranked r
where e.id=r.id and r.rn>1
  and not exists (select 1 from invitations i where i.event_id=e.id);

