 ('Breakbeat Girls','breakbeat-girls-medan-2026','konser','medan','Helen''s Medan','2026-11-19','2026-11-24','Info menyusul','Electronic','Vika Chu (19 Nov), Berlin (24 Nov)','Rangkaian malam electronic di Helen''s Medan, 19–24 November 2026: Vika Chu pada 19 November dan Berlin pada 24 November. Harga dan jam tayang belum diumumkan.','https://infokonser.id/storage/uploads/media/2026/11/01M7A9E38KQ2Q9W4XS9B4KYAPA/800w.webp','https://infokonser.id/konser/breakbeat-girls','infokonser_official'),
 ('BLUEPHORIA','bluephoria-pontianak-2026','konser','pontianak','Gedung Auditorium Universitas Tanjungpura, Pontianak','2026-11-26','2026-11-26','Mulai Rp100.000','Pop / Festival','Line-up menyusul','Malam penutup Dies Natalis ke-61 FISIP Untan, Kamis 26 November 2026 pukul 15.00–22.30 WIB, memadukan penampilan musik dan hiburan dalam satu panggung.','https://infokonser.id/storage/uploads/media/2026/11/01M70E3VZS8A5P13NDH0YB4FEY/800w.webp','https://infokonser.id/out/tickets/01M70E3VH5V9XV92YTXYHGWW0R','infokonser_official'),
 ('November Summerfest 2026','november-summerfest-2026-lamongan','konser','lamongan','Sport Center Lamongan (GOR), Lamongan','2026-11-22','2026-11-22','Mulai Rp70.000','Metal','Line-up menyusul','Festival metal underground oleh komunitas Lamongan Metal Madness, Minggu 22 November 2026 pukul 13.00–21.00 WIB; kembali ke GOR yang sama setelah 14 tahun. Promotor Vision Ground.','https://infokonser.id/storage/uploads/media/2026/10/01M56P84CTWCPM69WAC6TSMQ04/800w.webp','https://infokonser.id/out/tickets/01M6C9H5GZRC8V3ZMH91VQXTYV','infokonser_official')
) as v(title,slug,category,city,venue,d,e,price,genre,lineup,descr,poster,ticket,ig)
join cities c on c.slug=v.city
where not exists (
  select 1 from events x
  where x.slug=v.slug
     or (x.city_id=c.id and x.event_date=v.d::date and left(gwm_norm(x.title),10)=left(gwm_norm(v.title),10))
);

-- ===== 5. Lengkapi harga & poster event lama =====
update events e set price_label=v.price,
  poster_url=coalesce(v.poster,e.poster_url),
  ticket_url=coalesce(e.ticket_url,v.ticket)
from (values
 ('joyland-sessions-2026','Rp588.000 – Rp1.188.000 (2-day pass)','https://infokonser.id/storage/uploads/media/2026/10/01M59BW9X2WFM7ZY324KDVYS5J/800w.webp','https://infokonser.id/out/tickets/01M6C9KY5J4EY2QRNWNADEBYT5'),
 ('bts-arirang-jakarta-2026','Rp1.800.000 – Rp4.500.000 (di luar pajak & biaya admin)',null,null),
 ('5sos-jakarta-2026','Rp910.000 – Rp5.000.000 (acuan show 14 Nov; cek 5sosjakarta.com)',null,null)
) as v(slug,price,poster,ticket)
where e.slug=v.slug;
-- Harga kosong -> tulis jelas "Info menyusul" (tidak ada kolom harga yang kosong)
update events set price_label='Info menyusul' where price_label is null or trim(price_label)='';

-- ===== 5b. Terbitkan konser Bandung & Jakarta yang tadinya draft (data sudah lengkap: poster, harga, link tiket) =====
update events set status='published' where status='draft' and slug in (
 'ruang-riang-wow-ma-jakarta-2026','ruang-riang-wow-ma-bandung-2026','soundrenaline-sana-sini-bandung',
 'harmonic-the-cure-olivia-rodrigo-karaoke-bandung','bandung-bernyanyi-vol17','boomfest-bandung',
 'konser-nasyid-nostalgia','konser-gemerlap-2026','manfest-new-era-bandung-2026','kickfest-rediscover-xvii',
 'side-on-stage','amerta-rasa-2026','darurat-pesta');

-- ===== 6. Kunci permanen: database menolak duplikat berikutnya =====
do $$ begin
  create unique index if not exists events_no_dupe on events(city_id,event_date,gwm_norm(title));
exception when others then
  raise notice 'Index anti-duplikat belum dibuat (masih ada duplikat yang dipakai ajakan): %', sqlerrm;
end $$;

